// This player's carry actions, shown before the Multiplayer Server answers. Pending actions are replayed in order
// over the latest server state; one that no longer applies there (already confirmed, or overtaken) is dropped,
// a refused one is rolled back by reject(), and none outlives CONFIRMATION_MS.
import { applyCarry, type CarryAction, type CarryEvent, type CarryRules, type CarryState } from './carryRules'

interface PendingAction { id: number; action: CarryAction; at: number }

export const CONFIRMATION_MS = 3000

export class CarryPrediction {
  private base: CarryState | null = null
  private pending: PendingAction[] = []
  private sequence = 0

  constructor(private readonly rules: () => CarryRules, private readonly player: () => string) {}

  reconcile(state: CarryState, now: number): void {
    this.base = state
    this.replay(now, true)
  }

  view(now: number): CarryState | null {
    return this.replay(now, false)
  }

  predict(action: CarryAction, now: number): { id: number | null; message: string; events: CarryEvent[] } {
    const state = this.view(now)
    if (state === null) return { id: null, message: '', events: [] }
    const result = applyCarry(state, action, this.player(), this.rules(), now)
    if (!result.accepted) return { id: null, message: result.message, events: [] }
    const id = ++this.sequence
    this.pending.push({ id, action, at: now })
    return { id, message: result.message, events: result.events }
  }

  reject(id: number): boolean {
    const count = this.pending.length
    this.pending = this.pending.filter((pending) => pending.id !== id)
    return this.pending.length !== count
  }

  get pendingCount(): number {
    return this.pending.length
  }

  private replay(now: number, prune: boolean): CarryState | null {
    if (this.base === null) return null
    let state = this.base
    const kept: PendingAction[] = []
    for (const pending of this.pending) {
      if (now - pending.at >= CONFIRMATION_MS) continue
      const result = applyCarry(state, pending.action, this.player(), this.rules(), pending.at)
      if (!result.accepted) {
        if (!prune) kept.push(pending)
        continue
      }
      state = result.state
      kept.push(pending)
    }
    this.pending = kept
    return state
  }
}
